#define FILE_NAME ""

void execute(int n)
{
    int k;
    cin >> k;

    typedef double T;
    vector<T> probabilities(n);
    for (int i = 0; i < n; i++)
        cin >> probabilities[i];

    T dp[2][1 << n];
    memset(dp, 0, sizeof dp);

    vector<char> valid(n);
    vi valid_list;
    for (int i = 0; i < n; i++)
        if (probabilities[i] != 0)
        {
            valid[i] = 1;
            valid_list.push_back(i);
        }

    dp[0][0] = 1;
    int toggle = 1;

    vector<T> prefix_sum(1 << n);
    prefix_sum[0] = 1.0;
    for (int mask = 1; mask < (1 << n); ++mask)
    {
        int pos = __builtin_ctz(mask);
        assert(((mask >> pos) & 1) == 1);
        prefix_sum[mask] = prefix_sum[mask ^ (1 << pos)] - probabilities[pos];
    }

    for (int step = 0; step < min(sz(valid_list), k); ++step)
