            for (int nxt : valid_list)
                if (!((mask >> nxt) & 1))
                {
                    dp[toggle][mask ^ (1 << nxt)] += dp[toggle ^ 1][mask] * probabilities[nxt] / prefix_sum[mask];
                }
        }
        toggle ^= 1;
    }

    toggle ^= 1;
    for (int i = 0; i < n; ++i)
    {
        if (!valid[i])
            printf("%.12f ", 0.0);
        else
        {
            T total_prob = 0;
            for (int mask = 0; mask < (1 << n); ++mask)
                if (((mask >> i) & 1))
                    total_prob += dp[toggle][mask];
            printf("%.12f ", (double)total_prob);
        }
        puts("");
    }
}

